import{_ as e,o as l,c as a,a3 as n}from"./chunks/framework.bvEHUNtb.js";const x=JSON.parse('{"title":"C-09 九州","description":"对照先秦文献、邹衍大九州说与历史地理变迁，理解九州如何成为华夏认同的文化符号。","frontmatter":{"title":"C-09 九州","description":"对照先秦文献、邹衍大九州说与历史地理变迁，理解九州如何成为华夏认同的文化符号。","category":"guide","outline":"deep","aliases":["九州","大九州说","禹贡九州"]},"headers":[],"relativePath":"topics/traditional-wisdom/common-knowledge/nine-provinces.md","filePath":"topics/traditional-wisdom/common-knowledge/nine-provinces.md","lastUpdated":1786982540000}'),s={name:"topics/traditional-wisdom/common-knowledge/nine-provinces.md"};function r(d,t,i,o,g,p){return l(),a("div",null,[...t[0]||(t[0]=[n(`<h1 id="c-09-·-九州-地理区划与文化认同" tabindex="-1">C-09 · 九州：地理区划与文化认同 <a class="header-anchor" href="#c-09-·-九州-地理区划与文化认同" aria-label="Permalink to &quot;C-09 · 九州：地理区划与文化认同&quot;">​</a></h1><h2 id="先秦各书的九州异同-·-邹衍大九州说-·-九州作为华夏认同的文化符号" tabindex="-1">先秦各书的九州异同 · 邹衍大九州说 · 九州作为华夏认同的文化符号 <a class="header-anchor" href="#先秦各书的九州异同-·-邹衍大九州说-·-九州作为华夏认同的文化符号" aria-label="Permalink to &quot;先秦各书的九州异同 · 邹衍大九州说 · 九州作为华夏认同的文化符号&quot;">​</a></h2><p><strong>系列：</strong> 中华传统智慧体系 · 通识基础知识库 · 文化通识篇（C系列）· 地理方位组<br><strong>版本：</strong> v1.0（2026年8月）<br><strong>前置篇目（必读）：</strong> 主干04·五行论 / C-08·五方五岳<br><strong>后续篇目：</strong> C-10·三才（天地人）<br><strong>平行篇目：</strong> C-08·五方五岳</p><hr><h2 id="写在前面-为什么要专门讲九州" tabindex="-1">写在前面：为什么要专门讲九州？ <a class="header-anchor" href="#写在前面-为什么要专门讲九州" aria-label="Permalink to &quot;写在前面：为什么要专门讲九州？&quot;">​</a></h2><p>&quot;九州&quot;是中国人最熟悉的文化符号之一。<br> &quot;九州大地&quot;&quot;九州同&quot;&quot;问苍茫大地，谁主九州&quot;——<br> 这个词，几乎等同于&quot;中国&quot;本身。</p><p>但这个&quot;常识&quot;背后，藏着几个鲜少被认真对待的问题：</p><ul><li><strong>&quot;九州&quot;到底是哪九个州？</strong> 先秦不同文献的记载，彼此不一致。</li><li><strong>《禹贡》的九州，真的是大禹划定的吗？</strong> 成书年代本身就是学术争议。</li><li><strong>邹衍的&quot;大九州说&quot;是什么？</strong> 这个被司马迁专门记载的理论，挑战了整个传统天下观。</li><li><strong>&quot;九州&quot;作为中国代称，是怎么形成的？</strong> 从地理区划到文化符号，这个演变过程值得仔细梳理。</li></ul><p><strong>本篇的写作立场：</strong><br> 先秦原典怎么说，逐一呈现；各书异同，如实对比；存疑之处，明确标注，不以&quot;定论&quot;方式处理。</p><hr><h2 id="一、俯瞰-九州在体系中的位置" tabindex="-1">一、俯瞰：九州在体系中的位置 <a class="header-anchor" href="#一、俯瞰-九州在体系中的位置" aria-label="Permalink to &quot;一、俯瞰：九州在体系中的位置&quot;">​</a></h2><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>宇宙结构观</span></span>
<span class="line"><span>  └─ 五行论（主干04）</span></span>
<span class="line"><span>       └─ 五方（东·南·中·西·北）</span></span>
<span class="line"><span>            └─ 五岳（C-08）——五方的山岳锚点</span></span>
<span class="line"><span>            └─ 九州（C-09）——五方框架在行政地理上的展开</span></span>
<span class="line"><span>                 ├─ 地理区划（大禹治水后的空间秩序）</span></span>
<span class="line"><span>                 ├─ 政治象征（天下一统的合法性依据）</span></span>
<span class="line"><span>                 └─ 文化认同（华夏民族的共同地理想象）</span></span></code></pre></div><p><strong>一句话定位：</strong><br> 九州是先人将五行五方的哲学框架投射到具体大地上的<strong>行政地理想象</strong>——它不只是一套区划方案，而是&quot;天下&quot;观念在地理空间上的完整表达。</p><h2 id="二、九州的文献起点-大禹治水" tabindex="-1">二、九州的文献起点：大禹治水 <a class="header-anchor" href="#二、九州的文献起点-大禹治水" aria-label="Permalink to &quot;二、九州的文献起点：大禹治水&quot;">​</a></h2><h3 id="_2-1-最早的叙述框架" tabindex="-1">2.1 最早的叙述框架 <a class="header-anchor" href="#_2-1-最早的叙述框架" aria-label="Permalink to &quot;2.1 最早的叙述框架&quot;">​</a></h3><p>【原典】《尚书·禹贡》<br> 【原文】禹敷土，随山刊木，奠高山大川。<br> 冀州既载……济河惟兖州……<br> 海岱惟青州……海岱及淮惟徐州……<br> 淮海惟扬州……荆及衡阳惟荆州……<br> 荆河惟豫州……华阳黑水惟梁州……<br> 黑水西河惟雍州。<br> 【版本】《尚书》</p><p>《禹贡》的叙述框架是：大禹治水之后，按山川地势将天下划分为九州，并为每州规定了土壤、物产、贡赋等级。</p><p><strong>《禹贡》九州名单：</strong><br> 冀州·兖州·青州·徐州·扬州·荆州·豫州·梁州·雍州</p><h3 id="_2-2-⚠️-存疑标注-《禹贡》的成书年代" tabindex="-1">2.2 ⚠️ 存疑标注：《禹贡》的成书年代 <a class="header-anchor" href="#_2-2-⚠️-存疑标注-《禹贡》的成书年代" aria-label="Permalink to &quot;2.2 ⚠️ 存疑标注：《禹贡》的成书年代&quot;">​</a></h3><p>【原典】《论禹贡著成的时代》，傅斯年，中央研究院历史语言研究所集刊<br> 【原文】禹贡的九州，和周礼夏官职方、吕氏春秋有始览、尔雅释地等所说的九州，互有出入。 所谓禹迹的九州，大概是某一个（或数个）政治理想的表现，而非真实的历史地理记录。<br> 【版本】傅斯年，中央研究院历史语言研究所集刊，1933年</p><p><strong>需要如实指出的是：</strong><br> 《禹贡》虽托名大禹，但其成书年代学界争议颇大。 <strong>傅斯年等学者</strong>认为，《禹贡》很可能成书于战国时期，是战国士人托古立说、表达政治理想的文本，而非真实的上古地理记录。</p><p>这不影响《禹贡》的文化和历史价值。</p><h2 id="三、先秦各书的九州-异同对比" tabindex="-1">三、先秦各书的九州：异同对比 <a class="header-anchor" href="#三、先秦各书的九州-异同对比" aria-label="Permalink to &quot;三、先秦各书的九州：异同对比&quot;">​</a></h2><p>这是本篇最需要仔细呈现的部分。先秦文献中，至少有五个版本的&quot;九州&quot;，彼此不完全一致。</p><h3 id="_3-1-五个版本的完整对比" tabindex="-1">3.1 五个版本的完整对比 <a class="header-anchor" href="#_3-1-五个版本的完整对比" aria-label="Permalink to &quot;3.1 五个版本的完整对比&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">州名</th><th style="text-align:center;">禹贡</th><th style="text-align:center;">周礼·职方</th><th style="text-align:center;">吕氏春秋·有始</th><th style="text-align:center;">尔雅·释地</th><th style="text-align:center;">逸周书·职方</th></tr></thead><tbody><tr><td style="text-align:left;">冀州</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr><tr><td style="text-align:left;">兖州</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr><tr><td style="text-align:left;">青州</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr><tr><td style="text-align:left;">徐州</td><td style="text-align:center;">✓</td><td style="text-align:center;">—</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">—</td></tr><tr><td style="text-align:left;">扬州</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr><tr><td style="text-align:left;">荆州</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr><tr><td style="text-align:left;">豫州</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr><tr><td style="text-align:left;"><strong>梁州</strong></td><td style="text-align:center;">✓</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td></tr><tr><td style="text-align:left;">雍州</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr><tr><td style="text-align:left;"><strong>幽州</strong></td><td style="text-align:center;">—</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr><tr><td style="text-align:left;"><strong>并州</strong></td><td style="text-align:center;">—</td><td style="text-align:center;">✓</td><td style="text-align:center;">—</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr><tr><td style="text-align:left;"><strong>营州</strong></td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">✓</td><td style="text-align:center;">—</td></tr></tbody></table><h3 id="_3-2-核心差异说明" tabindex="-1">3.2 核心差异说明 <a class="header-anchor" href="#_3-2-核心差异说明" aria-label="Permalink to &quot;3.2 核心差异说明&quot;">​</a></h3><p><strong>差异最大的三个州：</strong></p><p><strong>① 梁州（仅见于《禹贡》）</strong><br> 梁州位于今四川·陕南一带，是《禹贡》独有的州名。<br> 《周礼》《吕氏春秋》均以<strong>雍州</strong>涵盖这一区域，<br> 不单独列出梁州。</p><p><strong>② 徐州（《禹贡》《吕氏春秋》有，《周礼》无）</strong><br> 徐州位于今苏北·鲁南一带。<br> 《周礼·职方》以<strong>幽州·并州</strong>替代了《禹贡》的徐州·梁州，<br> 反映了不同时代对北方疆域认知的扩展。</p><p><strong>③ 幽州·并州（《周礼》新增）</strong><br> 幽州（今河北北部·辽宁）、并州（今山西·河北西部），<br> 是《周礼》相对于《禹贡》新增的两个北方州，<br> 反映了周代对北方疆域的进一步认知与整合。$ CITE_1 $CITE_3</p><h3 id="_3-3-为什么各书不一致" tabindex="-1">3.3 为什么各书不一致？ <a class="header-anchor" href="#_3-3-为什么各书不一致" aria-label="Permalink to &quot;3.3 为什么各书不一致？&quot;">​</a></h3><p>【原典】《&quot;禹画九州&quot;传说流变析论》，西南大学学报<br> 【原文】各书九州说法互有出入，盖因九州之说本非一时一地之产物，而是不同时期、不同地域的政治理想与地理认知叠加积累的结果。<br> 【版本】西南大学学报（社会科学版），2020年第1期</p><p><strong>根本原因：</strong><br> 九州不是一次性划定的客观地理事实，而是不同时代的士人，根据各自的政治理想与地理认知，反复书写、修订的<strong>文化建构</strong>。</p><p>每个版本的九州，都反映了其成书时代的：</p><ul><li>疆域认知（知道多大范围的土地）</li><li>政治理想（希望&quot;天下&quot;包含哪些区域）</li><li>文化认同（哪些地方属于&quot;华夏&quot;）</li></ul><h2 id="四、邹衍的大九州说-挑战传统天下观" tabindex="-1">四、邹衍的大九州说：挑战传统天下观 <a class="header-anchor" href="#四、邹衍的大九州说-挑战传统天下观" aria-label="Permalink to &quot;四、邹衍的大九州说：挑战传统天下观&quot;">​</a></h2><h3 id="_4-1-邹衍是谁" tabindex="-1">4.1 邹衍是谁？ <a class="header-anchor" href="#_4-1-邹衍是谁" aria-label="Permalink to &quot;4.1 邹衍是谁？&quot;">​</a></h3><p>邹衍（约前305—前240年），战国末期齐国人，<br> 阴阳家的代表人物，司马迁在《史记》中专门为其立传。</p><h3 id="_4-2-大九州说的核心内容" tabindex="-1">4.2 大九州说的核心内容 <a class="header-anchor" href="#_4-2-大九州说的核心内容" aria-label="Permalink to &quot;4.2 大九州说的核心内容&quot;">​</a></h3><p>【原典】《史记·孟子荀卿列传》<br> 【原文】以为儒者所谓中国者，於天下乃八十一分居其一分耳。中国名曰赤县神州。赤县神州内自有九州，禹之序九州是也，不得为州数。中国外如赤县神州者九，乃所谓九州也。有裨海环之，人民禽兽莫能相通也，如一区中者，乃为一州。如此者九，乃有大瀛海环其外，天地之际焉。<br> 【版本】西汉·司马迁撰，中华书局点校本（二十四史）</p><p><strong>邹衍的大九州说，用现代语言表达：</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>传统儒家的&quot;九州&quot; = 禹贡九州 = 中国（赤县神州）内部的划分</span></span>
<span class="line"><span>                                  ↓</span></span>
<span class="line"><span>邹衍的&quot;大九州&quot; = 世界由九个&quot;赤县神州&quot;组成</span></span>
<span class="line"><span>                  每个&quot;赤县神州&quot;内部各有九州</span></span>
<span class="line"><span>                  整个世界 = 9 × 9 = 81个小州</span></span>
<span class="line"><span>                  中国（禹贡九州）只占世界的 1/81</span></span></code></pre></div><h3 id="_4-3-大九州说的思想意义" tabindex="-1">4.3 大九州说的思想意义 <a class="header-anchor" href="#_4-3-大九州说的思想意义" aria-label="Permalink to &quot;4.3 大九州说的思想意义&quot;">​</a></h3><p>【原典】《&quot;九州&quot;诸说评议》，中国社会科学网<br> 【原文】阴阳家邹衍提出的&#39;大九州&#39;说，其划分方式挑战了儒家&#39;王者居天下之中&#39;的传统观念，建立了以世界为整体的天下观。<br> 【版本】中国社会科学网，2023年1月</p><p><strong>邹衍大九州说的三重意义：</strong></p><p><strong>① 宇宙观的扩张</strong><br> 将&quot;天下&quot;从华夏九州扩展到整个世界，<br> 是先秦思想中罕见的&quot;世界主义&quot;视野。</p><p><strong>② 对儒家中心论的挑战</strong><br> 儒家以&quot;中国居天下之中&quot;为政治合法性基础；<br> 邹衍的大九州说指出：中国不过是世界八十一分之一，这从根本上动摇了&quot;华夏中心&quot;的宇宙论基础。</p><p><strong>③ 阴阳家的数理思维</strong><br> 9×9=81，这不是随机的数字，而是阴阳家以&quot;九&quot;（阳数之极）为基础的数理推演——<br> 与律数体系中黄钟基准81（$$ 9\\times9 $$ ） $同源。</p><h3 id="_4-4-大九州说的历史命运" tabindex="-1">4.4 大九州说的历史命运 <a class="header-anchor" href="#_4-4-大九州说的历史命运" aria-label="Permalink to &quot;4.4 大九州说的历史命运&quot;">​</a></h3><p>邹衍的大九州说，在历史上的命运颇为耐人寻味：</p><ul><li>司马迁认为其说&quot;宏大不经&quot;，但仍专门记载，可见其影响力。</li><li>汉代以后，随着儒家独尊，大九州说逐渐边缘化。</li><li>但&quot;赤县神州&quot;作为中国的雅称，却流传至今——这是一个思想体系被压制、但其语言符号存活下来的典型案例。</li></ul><h2 id="五、九州作为华夏认同的文化符号" tabindex="-1">五、九州作为华夏认同的文化符号 <a class="header-anchor" href="#五、九州作为华夏认同的文化符号" aria-label="Permalink to &quot;五、九州作为华夏认同的文化符号&quot;">​</a></h2><h3 id="_5-1-从地理区划到文化代称" tabindex="-1">5.1 从地理区划到文化代称 <a class="header-anchor" href="#_5-1-从地理区划到文化代称" aria-label="Permalink to &quot;5.1 从地理区划到文化代称&quot;">​</a></h3><p>【原典】《中华民族大一统观念的文化地理建构》<br> 【原文】它托名大禹，将中华大地划分为整齐的九州，并以此为基础，设计了一个围绕中心、包容四方的五服制度。如此，&#39;九州&#39;就成为华夏的代称，《禹贡》也被赋予了大一统的象征意义。&quot;<br> 【版本】《中华民族大一统观念的文化地理建构》，中国文化与认知科学学会，2024年</p><p>九州从地理区划演变为华夏代称，经历了一个关键的意义转换：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>地理事实层面：大禹治水，划分九州（文化叙事）</span></span>
<span class="line"><span>     ↓</span></span>
<span class="line"><span>礼制层面：《禹贡》五服制度——以九州为核心，向外辐射</span></span>
<span class="line"><span>     ↓</span></span>
<span class="line"><span>政治层面：九州 = 天下 = 王权合法性的地理基础</span></span>
<span class="line"><span>     ↓</span></span>
<span class="line"><span>文化层面：九州 = 华夏 = 中华民族的共同地理想象</span></span></code></pre></div><h3 id="_5-2-五服制度-九州的政治延伸" tabindex="-1">5.2 五服制度：九州的政治延伸 <a class="header-anchor" href="#_5-2-五服制度-九州的政治延伸" aria-label="Permalink to &quot;5.2 五服制度：九州的政治延伸&quot;">​</a></h3><blockquote><p>【原典】《尚书·禹贡》<br> 【原文】&quot;五百里甸服……五百里侯服……<br> 五百里绥服……五百里要服……<br> 五百里荒服。&quot;<br> 【版本】《尚书》，中华书局十三经注疏本</p></blockquote><p>《禹贡》在划定九州之后，<br> 紧接着设计了&quot;五服&quot;制度：<br> 以王畿（天子直辖地）为中心，<br> 向外每五百里为一服，共五服。</p><table tabindex="0"><thead><tr><th style="text-align:left;">服名</th><th style="text-align:left;">距王畿</th><th style="text-align:left;">性质</th></tr></thead><tbody><tr><td style="text-align:left;">甸服</td><td style="text-align:left;">500里内</td><td style="text-align:left;">直接供赋，天子直辖</td></tr><tr><td style="text-align:left;">侯服</td><td style="text-align:left;">500—1000里</td><td style="text-align:left;">诸侯朝贡</td></tr><tr><td style="text-align:left;">绥服</td><td style="text-align:left;">1000—1500里</td><td style="text-align:left;">教化推行区</td></tr><tr><td style="text-align:left;">要服</td><td style="text-align:left;">1500—2000里</td><td style="text-align:left;">羁縻管理区</td></tr><tr><td style="text-align:left;">荒服</td><td style="text-align:left;">2000—2500里</td><td style="text-align:left;">边荒朝贡区</td></tr></tbody></table><p><strong>五服制度的深层逻辑：</strong><br> 九州是横向的空间划分（东西南北中）；<br> 五服是纵向的权力辐射（由近及远）。<br> 两者叠加，构成了先人对&quot;天下秩序&quot;的完整空间想象。$CITE_4</p><h3 id="_5-3-历代王朝对九州的继承与发展" tabindex="-1">5.3 历代王朝对九州的继承与发展 <a class="header-anchor" href="#_5-3-历代王朝对九州的继承与发展" aria-label="Permalink to &quot;5.3 历代王朝对九州的继承与发展&quot;">​</a></h3><blockquote><p>【原典】《文化中国·九州共贯、多元一体的大一统传统》，求是网<br> 【原文】&quot;《尚书·禹贡》记载大禹划分九州，<br> 为&#39;共贯&#39;提供了初步的地理空间想象……<br> 为管理辽阔疆域，元朝创立行省制度，<br> 其行政区划打破&#39;山川形便&#39;的旧制。&quot;<br> 【版本】求是网，2026年4月</p></blockquote><p>九州对后世行政区划的影响：</p><table tabindex="0"><thead><tr><th style="text-align:left;">时代</th><th style="text-align:left;">区划制度</th><th style="text-align:left;">与九州的关系</th></tr></thead><tbody><tr><td style="text-align:left;">秦汉</td><td style="text-align:left;">郡县制</td><td style="text-align:left;">以九州为文化框架，郡县为实际单位</td></tr><tr><td style="text-align:left;">魏晋南北朝</td><td style="text-align:left;">州郡县三级制</td><td style="text-align:left;">&quot;州&quot;作为行政单位正式确立，直接继承九州名称</td></tr><tr><td style="text-align:left;">隋唐</td><td style="text-align:left;">道·州·县</td><td style="text-align:left;">贞观十道大体对应九州地理范围</td></tr><tr><td style="text-align:left;">宋</td><td style="text-align:left;">路·州·县</td><td style="text-align:left;">延续州制，九州仍为文化代称</td></tr><tr><td style="text-align:left;">元</td><td style="text-align:left;">行省制</td><td style="text-align:left;">打破山川形便，行省制度取代九州区划逻辑</td></tr><tr><td style="text-align:left;">明清</td><td style="text-align:left;">省·府·县</td><td style="text-align:left;">省制确立，九州退出行政实用，成为纯文化符号</td></tr></tbody></table><p>$CITE_4</p><hr><h2 id="六、九州的完整名单与地理对应" tabindex="-1">六、九州的完整名单与地理对应 <a class="header-anchor" href="#六、九州的完整名单与地理对应" aria-label="Permalink to &quot;六、九州的完整名单与地理对应&quot;">​</a></h2><h3 id="_6-1-《禹贡》九州-最具代表性的版本" tabindex="-1">6.1 《禹贡》九州：最具代表性的版本 <a class="header-anchor" href="#_6-1-《禹贡》九州-最具代表性的版本" aria-label="Permalink to &quot;6.1 《禹贡》九州：最具代表性的版本&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">州名</th><th style="text-align:left;">大致范围（今地）</th><th style="text-align:left;">核心山川</th><th style="text-align:left;">五行方位</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>冀州</strong></td><td style="text-align:left;">山西·河北·辽宁南部</td><td style="text-align:left;">黄河·太行山</td><td style="text-align:left;">中·北</td></tr><tr><td style="text-align:left;"><strong>兖州</strong></td><td style="text-align:left;">山东西部·河南东北</td><td style="text-align:left;">济水·黄河</td><td style="text-align:left;">东</td></tr><tr><td style="text-align:left;"><strong>青州</strong></td><td style="text-align:left;">山东东部·辽东</td><td style="text-align:left;">泰山·渤海</td><td style="text-align:left;">东</td></tr><tr><td style="text-align:left;"><strong>徐州</strong></td><td style="text-align:left;">苏北·鲁南·皖北</td><td style="text-align:left;">淮河·泗水</td><td style="text-align:left;">东南</td></tr><tr><td style="text-align:left;"><strong>扬州</strong></td><td style="text-align:left;">江苏·浙江·安徽南部</td><td style="text-align:left;">长江·淮河</td><td style="text-align:left;">南</td></tr><tr><td style="text-align:left;"><strong>荆州</strong></td><td style="text-align:left;">湖北·湖南</td><td style="text-align:left;">荆山·衡山</td><td style="text-align:left;">南</td></tr><tr><td style="text-align:left;"><strong>豫州</strong></td><td style="text-align:left;">河南·湖北北部</td><td style="text-align:left;">嵩山·黄河</td><td style="text-align:left;">中</td></tr><tr><td style="text-align:left;"><strong>梁州</strong></td><td style="text-align:left;">四川·陕南·甘南</td><td style="text-align:left;">华山·黑水</td><td style="text-align:left;">西</td></tr><tr><td style="text-align:left;"><strong>雍州</strong></td><td style="text-align:left;">陕西·甘肃·青海</td><td style="text-align:left;">黄河上游·龙门</td><td style="text-align:left;">西·北</td></tr></tbody></table><p>$CITE_1</p><h3 id="_6-2-冀州为何排第一" tabindex="-1">6.2 冀州为何排第一？ <a class="header-anchor" href="#_6-2-冀州为何排第一" aria-label="Permalink to &quot;6.2 冀州为何排第一？&quot;">​</a></h3><p>《禹贡》以冀州为九州之首，这有其深刻的政治地理逻辑：</p><blockquote><p>【原典】《尚书·禹贡》孔颖达疏<br> 【原文】&quot;冀州，帝都之所在，故最先言之。&quot;<br> 【版本】唐·孔颖达撰，中华书局十三经注疏本</p></blockquote><p>冀州是传说中尧·舜·禹的都城所在地，<br> 是华夏文明的政治发源地。<br> 以冀州为首，是《禹贡》政治叙事的核心设计——<br><strong>天下的秩序，从王都向外辐射。</strong>$CITE_1</p><hr><h2 id="七、⚠️-存疑部分-需要如实标注的问题" tabindex="-1">七、⚠️ 存疑部分：需要如实标注的问题 <a class="header-anchor" href="#七、⚠️-存疑部分-需要如实标注的问题" aria-label="Permalink to &quot;七、⚠️ 存疑部分：需要如实标注的问题&quot;">​</a></h2><h3 id="_7-1-《禹贡》成书年代之争" tabindex="-1">7.1 《禹贡》成书年代之争 <a class="header-anchor" href="#_7-1-《禹贡》成书年代之争" aria-label="Permalink to &quot;7.1 《禹贡》成书年代之争&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">观点</th><th style="text-align:left;">代表学者</th><th style="text-align:left;">主要依据</th></tr></thead><tbody><tr><td style="text-align:left;">西周说</td><td style="text-align:left;">传统观点</td><td style="text-align:left;">托名大禹，文字古朴</td></tr><tr><td style="text-align:left;">春秋说</td><td style="text-align:left;">部分学者</td><td style="text-align:left;">地理知识与春秋时代吻合</td></tr><tr><td style="text-align:left;"><strong>战国说</strong></td><td style="text-align:left;"><strong>傅斯年·顾颉刚等</strong></td><td style="text-align:left;"><strong>地理范围·政治理想符合战国大一统思潮</strong></td></tr><tr><td style="text-align:left;">秦汉说</td><td style="text-align:left;">少数学者</td><td style="text-align:left;">部分地名与秦汉行政区划吻合</td></tr></tbody></table><p><strong>目前学界主流倾向：战国时期成书，托名大禹。</strong><br> 这不影响《禹贡》的文化价值，<br> 但需要区分&quot;文化叙事&quot;与&quot;历史事实&quot;。$CITE_1</p><h3 id="_7-2-九州范围的历史叙事问题" tabindex="-1">7.2 九州范围的历史叙事问题 <a class="header-anchor" href="#_7-2-九州范围的历史叙事问题" aria-label="Permalink to &quot;7.2 九州范围的历史叙事问题&quot;">​</a></h3><blockquote><p>【原典】《道中华·为什么我们以九州代指中国》，国家民委<br> 【原文】&quot;《禹贡》九州体现了大一统视野下的郡县·<br> 秦汉以降历代中央王朝实行郡县制·<br> 五服制的历史影响而逐渐形成的制度。&quot;<br> 【版本】国家民族事务委员会官网，2023年10月</p></blockquote><p>需要如实指出的是：<br> 《禹贡》九州的地理范围，<br> 基本覆盖黄河·长江流域的农耕文明核心区，<br> 对北方草原、西域、东南沿海等区域的描述极为有限。</p><p>**这说明九州的地理想象，<br> ****本质上是农耕华夏文明的自我认知边界，<br> **<strong>而非对整个东亚大陆的客观地理描述。</strong></p><p>后世将九州等同于&quot;中国全境&quot;，<br> 是一个随着王朝疆域扩展而不断被重新诠释的过程。$CITE_4</p><hr><h2 id="八、现代解读-九州的三重意义" tabindex="-1">八、现代解读：九州的三重意义 <a class="header-anchor" href="#八、现代解读-九州的三重意义" aria-label="Permalink to &quot;八、现代解读：九州的三重意义&quot;">​</a></h2><h3 id="_8-1-地理认知的文化建构" tabindex="-1">8.1 地理认知的文化建构 <a class="header-anchor" href="#_8-1-地理认知的文化建构" aria-label="Permalink to &quot;8.1 地理认知的文化建构&quot;">​</a></h3><p>九州，是先人用哲学框架（五行五方）<br> 对居住大地进行<strong>意义化</strong>的产物。<br> 它不是客观的地理测量，<br> 而是将大地纳入文化秩序的一种方式：</p><p><strong>大地不只是土地，而是有意义的空间。</strong><br> 每一块土地，都在&quot;天下&quot;的秩序中有其位置。</p><h3 id="_8-2-政治合法性的地理基础" tabindex="-1">8.2 政治合法性的地理基础 <a class="header-anchor" href="#_8-2-政治合法性的地理基础" aria-label="Permalink to &quot;8.2 政治合法性的地理基础&quot;">​</a></h3><p>&quot;九州&quot;作为&quot;天下&quot;的代称，<br> 为历代王朝提供了政治合法性的地理论证：<br> 谁统一了九州，谁就拥有了天命。</p><p>这是为什么历代开国皇帝都要强调&quot;混一九州&quot;——<br> 九州不只是地理概念，而是<strong>王权合法性的地理表达</strong>。$CITE_4</p><h3 id="_8-3-民族认同的共同想象" tabindex="-1">8.3 民族认同的共同想象 <a class="header-anchor" href="#_8-3-民族认同的共同想象" aria-label="Permalink to &quot;8.3 民族认同的共同想象&quot;">​</a></h3><blockquote><p>【原典】《何方家国·承载中华文明维系乡土认同》<br> 【原文】&quot;九州是中国古代对华夏大地的地理划分，<br> 源自《尚书·禹贡》，历经几千年，<br> 行政区划深刻影响着居住在这片土地上的人民。&quot;<br> 【版本】宁远县民族宗教事务局，2025年3月</p></blockquote><p>九州，是中华民族共同的地理想象。<br> 无论你来自哪个省、哪个地方，<br> &quot;九州大地&quot;这四个字，<br> 唤起的是同一种文化归属感。</p><p>这种归属感，不需要精确的地理知识，<br> 只需要共同的文化记忆——<br><strong>这正是文化符号最深层的力量。</strong>$CITE_3</p><hr><h2 id="九、跨体系接口" tabindex="-1">九、跨体系接口 <a class="header-anchor" href="#九、跨体系接口" aria-label="Permalink to &quot;九、跨体系接口&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">体系</th><th style="text-align:left;">本篇的作用</th><th style="text-align:left;">具体说明</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>主干04·五行论</strong></td><td style="text-align:left;">直接前置</td><td style="text-align:left;">九州的方位逻辑以五行五方为框架</td></tr><tr><td style="text-align:left;"><strong>C-08·五方五岳</strong></td><td style="text-align:left;">直接前置</td><td style="text-align:left;">五岳是五方的山岳锚点；九州是五方的行政地理展开</td></tr><tr><td style="text-align:left;"><strong>C-10·三才</strong></td><td style="text-align:left;">哲学同源</td><td style="text-align:left;">天地人三才与九州共同构成先人的宇宙空间秩序观</td></tr><tr><td style="text-align:left;"><strong>主干13·六十甲子</strong></td><td style="text-align:left;">时空对应</td><td style="text-align:left;">九州与天干地支的方位对应；古代占卜中的地理分野</td></tr><tr><td style="text-align:left;"><strong>奇门遁甲</strong></td><td style="text-align:left;">直接调用</td><td style="text-align:left;">奇门九宫对应九州；地理分野是奇门布局的空间基础</td></tr><tr><td style="text-align:left;"><strong>六爻</strong></td><td style="text-align:left;">直接调用</td><td style="text-align:left;">六爻分野说：各卦对应九州不同地域</td></tr><tr><td style="text-align:left;"><strong>Jing·周易</strong></td><td style="text-align:left;">文本背景</td><td style="text-align:left;">读《周易》古注时，分野·九州是高频背景知识</td></tr></tbody></table><hr><h2 id="十、本章小结" tabindex="-1">十、本章小结 <a class="header-anchor" href="#十、本章小结" aria-label="Permalink to &quot;十、本章小结&quot;">​</a></h2><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>九州 · 四句话总结：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. 文献事实：</span></span>
<span class="line"><span>   先秦至少五个版本的九州，各书不完全一致；</span></span>
<span class="line"><span>   《禹贡》（冀兖青徐扬荆豫梁雍）是最具代表性的版本，</span></span>
<span class="line"><span>   但其成书年代学界倾向战国，托名大禹，是政治理想的文化建构。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2. 邹衍大九州：</span></span>
<span class="line"><span>   战国阴阳家邹衍提出&quot;大九州说&quot;——</span></span>
<span class="line"><span>   禹贡九州只是&quot;赤县神州&quot;内部的小九州，</span></span>
<span class="line"><span>   世界由九个赤县神州组成，中国仅占世界八十一分之一；</span></span>
<span class="line"><span>   这是先秦最具世界主义视野的地理哲学。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>3. 存疑标注：</span></span>
<span class="line"><span>   《禹贡》成书年代存争议（主流倾向战国说）；</span></span>
<span class="line"><span>   九州地理范围本质上是农耕华夏文明的自我认知边界，</span></span>
<span class="line"><span>   后世等同于&quot;中国全境&quot;是随疆域扩展不断重新诠释的结果。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>4. 文化意义：</span></span>
<span class="line"><span>   九州从地理区划演变为华夏代称，</span></span>
<span class="line"><span>   经历了地理→礼制→政治→文化的意义层叠；</span></span>
<span class="line"><span>   它是中华民族共同地理想象的核心符号，</span></span>
<span class="line"><span>   也是历代王权合法性的地理表达基础。</span></span></code></pre></div><hr><h2 id="引用来源" tabindex="-1">引用来源 <a class="header-anchor" href="#引用来源" aria-label="Permalink to &quot;引用来源&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">编号</th><th style="text-align:left;">来源</th><th style="text-align:left;">核心内容</th></tr></thead><tbody><tr><td style="text-align:left;">1</td><td style="text-align:left;">《&quot;禹画九州&quot;传说流变析论》，西南大学学报（社会科学版），2020年第1期</td><td style="text-align:left;">先秦各书九州名单对比；《禹贡》成书年代争议；各书差异的根本原因</td></tr><tr><td style="text-align:left;">2</td><td style="text-align:left;">《史记·孟子荀卿列传》，西汉·司马迁撰，中华书局点校本</td><td style="text-align:left;">邹衍大九州说原文；&quot;赤县神州&quot;的来源；大九州说的思想意义</td></tr><tr><td style="text-align:left;">3</td><td style="text-align:left;">《&quot;九州&quot;诸说评议》，中国社会科学网，2023年1月</td><td style="text-align:left;">各版本九州的综合评议；邹衍大九州说对儒家中心论的挑战</td></tr><tr><td style="text-align:left;">4</td><td style="text-align:left;">《中华民族大一统观念的文化地理建构》，中国文化与认知科学学会，2024年</td><td style="text-align:left;">九州与五服制度；九州作为大一统象征的形成过程；历代王朝对九州的继承</td></tr><tr><td style="text-align:left;">5</td><td style="text-align:left;">《道中华·为什么我们以九州代指中国》，国家民族事务委员会官网，2023年10月</td><td style="text-align:left;">九州与郡县制的历史关联；九州作为华夏代称的文化演变</td></tr><tr><td style="text-align:left;">6</td><td style="text-align:left;">《论禹贡著成的时代》，傅斯年，中央研究院历史语言研究所集刊，1933年</td><td style="text-align:left;">《禹贡》成书年代的学术考证；九州作为政治理想而非历史事实的论证</td></tr></tbody></table><hr><p><strong>前置篇：</strong> C-08·五方五岳<br><strong>后续篇：</strong> C-10·三才（天地人）</p>`,109)])])}const c=e(s,[["render",r]]);export{x as __pageData,c as default};
